import { z } from "zod";
import {
  domainModelInputSchema,
  elementKinds,
  type DomainModelInput,
} from "./domain-model";

// Names are generated by the model; IDs and event associations belong to the app.
export const generatedModelSchema = z
  .object({
    name: z.string().min(1).max(100),
    description: z.string().max(5000),
    elements: z
      .array(
        z
          .object({
            kind: z.enum(elementKinds),
            name: z.string().min(1).max(100),
            description: z.string().max(5000),
            eventName: z.string().max(100).nullable(),
            fields: z
              .array(
                z
                  .object({
                    name: z.string().min(1).max(100),
                    dataType: z.string().min(1).max(100),
                    description: z.string().min(1).max(2000),
                  })
                  .strict(),
              )
              .max(50),
          })
          .strict(),
      )
      .min(5)
      .max(30),
  })
  .strict();

export const generateModelRequestSchema = z
  .object({
    prompt: z
      .string()
      .trim()
      .min(10, "请至少输入 10 个字符的需求")
      .max(12000, "需求最多 12000 个字符"),
    model: z.string().trim().min(1).max(200).optional(),
  })
  .strict();

export function normalizeGeneratedModel(value: unknown): DomainModelInput {
  const generated = generatedModelSchema.parse(value);
  const elements = generated.elements.map((element) => ({
    id: crypto.randomUUID(),
    kind: element.kind,
    name: element.name.trim(),
    description: element.description.trim(),
    fields: element.fields.map((field) => ({
      ...field,
      id: crypto.randomUUID(),
    })),
    eventId: null as string | null,
  }));
  for (const kind of elementKinds) {
    if (!elements.some((element) => element.kind === kind))
      throw new Error("生成结果缺少设计项，请重新生成");
  }
  elements.forEach((element, index) => {
    const eventName = generated.elements[index]!.eventName;
    if (element.kind === "event_handler") {
      const event = elements.find(
        (item) =>
          item.kind === "domain_event" && item.name === eventName?.trim(),
      );
      if (!event)
        throw new Error(
          `处理器“${element.name}”未关联有效的领域事件，请重新生成`,
        );
      element.eventId = event.id;
    } else if (eventName !== null) {
      throw new Error("只有领域事件处理器可以关联领域事件，请重新生成");
    }
  });
  return domainModelInputSchema.parse({
    name: generated.name,
    description: generated.description,
    elements,
  });
}

export type CodexStatus = {
  ready: boolean;
  account: string | null;
  models: { id: string; name: string; isDefault: boolean }[];
};
export type ModelGenerationJob = {
  id: string;
  status: "queued" | "generating" | "completed" | "failed" | "cancelled";
  stage: string;
  createdAt: string;
  result?: DomainModelInput;
  error?: string;
};
